1590	
1591	// --- Parsing ---------------------------------------------------------------------------
1592	
1593	/// How a run of input left the parser when [`ParserMut::parse`] returns without an error:
1594	/// the outcomes `llhttp__internal_execute` reports through `HPE_OK` and its two resumable
1595	/// pauses, which llhttp's callers treat as an early stop, not a failure.
1596	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
1597	pub enum Parsed {
1598	    /// `HPE_OK`: the parser read every byte, and waits for more.
1599	    All,
1600	    /// `HPE_PAUSED`: a callback returned `HPE_PAUSED`, or the parser was paused before the
1601	    /// call, as `llhttp_pause` and [`ParserMut::set_error`] pause it. It stopped at its
1602	    /// error position ([`ParserRef::error_offset`]), and parses again once its error is
1603	    /// cleared, as `llhttp_resume` clears it; until then each parse returns `Paused` and
1604	    /// reads nothing.
1605	    Paused,
1606	    /// `HPE_PAUSED_UPGRADE`: the message upgraded the connection, so what follows its end,
1607	    /// from the error position on, is the new protocol's, not HTTP. The parser parses again
1608	    /// once its error is cleared, as `llhttp_resume_after_upgrade` clears it.
1609	    PausedUpgrade,
1610	}
1611	
1612	/// The error [`ParserMut::parse`] stopped at, as `llhttp__internal_execute` returns it: a
1613	/// nonzero `int` other than the two pauses, which the parser keeps as its error, so that
1614	/// every later parse returns it again until the parser is initialised again.
1615	///
1616	/// It is an `llhttp_errno` the parser set, or a data callback's own return value, which
1617	/// need be none ([`errno`](Self::errno)). The reason the parser or the callback gave is the
1618	/// parser's ([`ParserRef::reason`]), and so is where it stopped
1619	/// ([`ParserRef::error_offset`]).
1620	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
1621	pub struct ParseError(c_int);
1622	
1623	impl ParseError {
1624	    /// The `int` C returned.
1625	    #[must_use]
1626	    pub const fn code(self) -> c_int {
1627	        self.0
1628	    }
1629	
1630	    /// The error as llhttp's enum.
1631	    ///
1632	    /// # Errors
1633	    ///
1634	    /// [`UnnamedErrno`] when the code is no `llhttp_errno`: a data callback's own return
1635	    /// value, its bits as C's conversion to the unsigned enum gives them.
1636	    pub fn errno(self) -> Result<Errno, UnnamedErrno> {
1637	        Errno::try_from(self.0.cast_unsigned())
1638	    }
1639	}
1640	
1641	impl fmt::Display for ParseError {
1642	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
1643	        if let Some(errno) = Errno::from_raw(self.0.cast_unsigned()) {
1644	            f.write_str("llhttp stopped at ")?;
1645	            f.write_str(&errno.constant_name().to_string_lossy())
1646	        } else {
1647	            f.write_str("llhttp stopped at a callback's error ")?;
1648	            fmt::Display::fmt(&self.0, f)
1649	        }
1650	    }
1651	}
1652	
1653	impl std::error::Error for ParseError {}
1654	
1655	impl ParseError {
1656	    /// The outcome of a parse whose `llhttp__internal_execute` returned `code`.
1657	    const fn outcome(code: c_int) -> Result<Parsed, Self> {
1658	        match code.cast_unsigned() {
1659	            sys::HPE_OK => Ok(Parsed::All),
1660	            sys::HPE_PAUSED => Ok(Parsed::Paused),
1661	            sys::HPE_PAUSED_UPGRADE => Ok(Parsed::PausedUpgrade),
1662	            _ => Err(Self(code)),
1663	        }
1664	    }
1665	}
1666	
1667	// --- Callbacks -------------------------------------------------------------------------
1668	
1669	/// A Rust implementation of an [`Callback`]: the function C calls with the parser an event
1670	/// happened on.
1671	///
1672	/// It carries no state: `llhttp_cb` has no context parameter, and a parser's context is its
1673	/// `data`, which the callback reads through the parser it is handed. Its return value is
1674	/// the C callback's, whose meaning the settings slot it sits in gives: `0` to go on, `-1`
1675	/// for an error, `HPE_PAUSED` to pause, and for `on_headers_complete` also `1` to read no
1676	/// body and `2` to read none and pause as an upgrade. A panic is caught, and returns `-1`.
1677	///
1678	/// The parser is the parsing thread's: a handler cannot send it to another, which could
1679	/// parse it beside the parse that runs the handler.
1680	///
1681	/// ```compile_fail,E0277
1682	/// use std::ffi::c_int;
