1	//! Equivalence tests for `deps/llhttp/llhttp.c`'s parser and enums against the C.
2	//!
3	//! Each test builds two parsers from one description, each initialised by `llhttp_init`
4	//! and fed the same input by `llhttp_execute`: one is read through api.c's getters
5	//! (`llhttp_get_type`, `llhttp_get_errno`, `llhttp_get_error_pos`, …), the other through
6	//! the safe handles, and the two are compared after every step of a multi-call sequence:
7	//! a response read in pieces, a request with a method, an upgrade, an invalid message, a
8	//! callback's own error and a pause. The setters are compared by their effect on the C: a
9	//! field set through [`ParserMut`] on one parser and as C sets it on the other, then read
10	//! back by the C getters, and by the next `llhttp_execute`.
11	//!
12	//! The enums' discriminants are their bindgen constants by construction; the tests compare
13	//! the values C stores with the variants the safe getters return for them.
14	//!
15	//! The constructor and the parse are compared with `llhttp__internal_init` and
16	//! `llhttp__internal_execute`, called through the raw bindings on a second parser in the
17	//! same state: [`Parser::new`] and [`ParserMut::reinit`] byte for byte, private state
18	//! included, and [`ParserMut::parse`] by its outcome, the whole parser after each run, and
19	//! the callbacks its settings run, which are Rust handlers C calls through
20	//! [`DataCallback`] and [`Callback`]. The X-macros are compared with what C expands them
21	//! to: their text in `llhttp.h`, and api.c's `llhttp_errno_name`, `llhttp_method_name` and
22	//! `llhttp_status_name`, the three `switch`es over them.
23	
24	use std::ffi::{CStr, c_char, c_int};
25	use std::ptr;
26	
27	use ffibox::{CMutSeam, CRefSeam, CZeroable};
28	use libgit2_crustify::libgit2::deps::llhttp::llhttp::{
29	    Callback, DataCallback, DataHandler, Errno, EventHandler, Method, ParseError, Parsed, Parser,
30	    ParserMut, ParserRef, ParserType, Status,
31	};
32	use libgit2_crustify::sys::libgit2 as sys;
33	
34	/// `LENIENT_HEADERS`, `llhttp_lenient_flags`' first bit.
35	const LENIENT_HEADERS: u16 = 0x1;
36	
37	/// A parser initialised by C, as `llhttp_init(parser, parser_type, settings)` leaves it.
38	fn c_init(parser_type: ParserType, settings: *const sys::llhttp_settings_t) -> Parser {
39	    let mut parser = Parser::zeroed();
40	    // SAFETY: the handle addresses `parser`, a live `llhttp_t` Rust owns, which
41	    // `llhttp_init` fills in place; `settings` is NULL or a table the caller keeps alive
42	    // while the parser executes.
43	    unsafe { sys::llhttp_init(parser.as_mut().as_mut_ptr(), parser_type.raw(), settings) };
44	    parser
45	}
46	
47	/// Feeds `data` to `parser` through C, returning the `llhttp_errno` it reports.
48	fn c_execute(parser: &mut Parser, data: &[u8]) -> sys::llhttp_errno {
49	    // SAFETY: `parser` is initialised (`c_init`), `data` is `data.len()` readable bytes, and
50	    // its settings, if any, are live (`c_init`'s callers).
51	    unsafe {
52	        sys::llhttp_execute(
53	            parser.as_mut().as_mut_ptr(),
54	            data.as_ptr().cast(),
55	            data.len(),
56	        )
57	    }
58	}
59	
60	/// What api.c's getters read of a parser, in the safe API's terms.
61	#[derive(Debug, PartialEq, Eq)]
62	struct Fields {
63	    parser_type: u8,
64	    http_major: u8,
65	    http_minor: u8,
66	    method: u8,
67	    status_code: i32,
68	    upgrade: u8,
69	    errno: u32,
70	    reason: Option<Vec<u8>>,
71	    error_offset: Option<usize>,
72	}
73	
74	/// `parser`'s fields through api.c's getters, its error position as an offset into `data`.
75	fn c_fields(parser: &mut Parser, data: &[u8]) -> Fields {
76	    let p = parser.as_mut().as_mut_ptr();
77	    // SAFETY: `p` addresses a live, initialised `llhttp_t`; each getter reads its fields.
78	    let parser_type = unsafe { sys::llhttp_get_type(p) };
79	    // SAFETY: as above.
80	    let http_major = unsafe { sys::llhttp_get_http_major(p) };
81	    // SAFETY: as above.
82	    let http_minor = unsafe { sys::llhttp_get_http_minor(p) };
83	    // SAFETY: as above.
84	    let method = unsafe { sys::llhttp_get_method(p) };
85	    // SAFETY: as above.
86	    let status_code = unsafe { sys::llhttp_get_status_code(p) };
87	    // SAFETY: as above.
88	    let upgrade = unsafe { sys::llhttp_get_upgrade(p) };
89	    // SAFETY: as above.
90	    let errno = unsafe { sys::llhttp_get_errno(p) };
91	    // SAFETY: as above.
92	    let reason = unsafe { sys::llhttp_get_error_reason(p) };
93	    // SAFETY: a non-NULL reason is one of llhttp's string literals.
94	    let reason = (!reason.is_null()).then(|| unsafe { CStr::from_ptr(reason) }.to_bytes().to_vec());
95	    // SAFETY: as above.
96	    let pos = unsafe { sys::llhttp_get_error_pos(p) };
97	    let error_offset = (!pos.is_null())
98	        .then(|| pos.addr().checked_sub(data.as_ptr().addr()))
99	        .flatten()
100	        .filter(|&offset| offset <= data.len());
101	    Fields {
102	        parser_type,
103	        http_major,
104	        http_minor,
105	        method,
106	        status_code,
107	        upgrade,
108	        errno,
109	        reason,
110	        error_offset,
111	    }
