129	/// Feeds each piece of `input` to two parsers of `parser_type`, comparing their fields read
130	/// through C and through Rust before the first and after every piece; returns the parser
131	/// Rust read, and the errno of the last piece.
132	fn compare_pieces(parser_type: ParserType, pieces: &[&[u8]]) -> (Parser, sys::llhttp_errno) {
133	    let mut c = c_init(parser_type, ptr::null());
134	    let mut rust = c_init(parser_type, ptr::null());
135	    assert_eq!(c_fields(&mut c, &[]), rust_fields(rust.as_ref(), &[]));
136	    let mut last = sys::HPE_OK;
137	    for (step, piece) in pieces.iter().enumerate() {
138	        let c_errno = c_execute(&mut c, piece);
139	        let rust_errno = c_execute(&mut rust, piece);
140	        assert_eq!(c_errno, rust_errno, "step {step}");
141	        assert_eq!(
142	            c_fields(&mut c, piece),
143	            rust_fields(rust.as_ref(), piece),
144	            "step {step}"
145	        );
146	        last = rust_errno;
147	    }
148	    (rust, last)
149	}
