353	/// The `XX(NUM, NAME, STRING)` entries of the X-macro `name` in `llhttp.h`, in its order.
354	fn header_entries(name: &str) -> Vec<(u32, String, String)> {
355	    let header = std::fs::read_to_string(concat!(
356	        env!("CARGO_MANIFEST_DIR"),
357	        "/c/deps/llhttp/llhttp.h"
358	    ))
359	    .unwrap();
360	    let start = header.find(&format!("#define {name}(XX) \\\n")).unwrap();
361	    header[start..]
362	        .lines()
363	        .skip(1)
364	        .take_while(|line| line.trim_start().starts_with("XX("))
365	        .map(|line| {
366	            let inner = line
367	                .trim()
368	                .trim_start_matches("XX(")
369	                .trim_end_matches(") \\");
370	            let mut parts = inner.split(", ");
371	            let num = parts.next().unwrap().parse().unwrap();
372	            let entry_name = parts.next().unwrap().to_owned();
373	            let string = parts.next().unwrap().to_owned();
374	            assert_eq!(parts.next(), None, "{line}");
375	            (num, entry_name, string)
376	        })
377	        .collect()
378	}
