1	//! Equivalence tests for `deps/llhttp/api.c`'s settings table against the C.
2	//!
3	//! [`Settings::new`] is compared with `llhttp_settings_init` byte for byte, from a table
4	//! filled with garbage, and a table filled through [`SettingsMut`]'s setters with one C
5	//! fills field by field, slot for slot. [`ParserMut::set_settings`] is compared with
6	//! `llhttp_init`: two parsers given one table, one by C and one through the safe setter,
7	//! are compared whole after the call, after `llhttp_reset`, and by the callbacks C's
8	//! dispatchers run for each of a sequence of runs, `llhttp_finish` included, the two
9	//! parsers' outcomes and fields compared after each run.
10	//!
11	//! The parser's API api.c gives is compared with its C the same way, on pairs of parsers
12	//! brought to one state: [`ParserMut::pause`], [`ParserMut::resume`] and
13	//! [`ParserMut::resume_after_upgrade`] against `llhttp_pause`, `llhttp_resume` and
14	//! `llhttp_resume_after_upgrade` from each state, every pair of them in turn, the whole
15	//! parser compared after each call; [`ParserMut::execute`] against `llhttp_execute` over runs
16	//! interleaved with pauses and resumptions; the ten lenient setters against theirs, `int`
17	//! flags C reads as true included; and [`ParserMut::set_reason`] against
18	//! `llhttp_set_error_reason`.
19	//!
20	//! The lifecycle the same way: [`ParserMut::init`] against `llhttp_init` for each parser type,
21	//! [`ParserMut::reset`] against `llhttp_reset`, and [`ParserMut::finish`] against
22	//! `llhttp_finish` with `on_message_complete` returning `0`, `-1` and `HPE_PAUSED`, each from
23	//! a parser fresh, inside a message, between two, failed, paused at an upgrade and of both kinds
24	//! settled on a request, `data` and the lenient flags set, the whole parser compared after
25	//! each call and the next message parsed through C and Rust. The 23 dispatchers are compared
26	//! with api.c's, declared here since no header declares them, over tables that record, refuse
27	//! with `-1`, pause and return any other value, and with no table: their returns, the slots
28	//! they call with each run, and the whole parser after each call.
29	
30	use std::cell::RefCell;
31	use std::ffi::{CStr, c_char, c_int};
32	use std::mem::MaybeUninit;
33	use std::sync::Mutex;
34	
35	use ffibox::{CMutSeam, CRefSeam, CZeroable};
36	use libgit2_crustify::libgit2::deps::llhttp::api::{Settings, SettingsRef};
37	use libgit2_crustify::libgit2::deps::llhttp::llhttp::{
38	    Callback, DataCallback, DataHandler, EventHandler, ParseError, Parsed, Parser, ParserMut,
39	    ParserRef, ParserType,
40	};
41	use libgit2_crustify::sys::libgit2 as sys;
42	
43	/// The table's 23 slots as the addresses they hold, read through its raw layout.
44	fn raw_slots(settings: SettingsRef<'_>) -> [usize; 23] {
45	    const { assert!(size_of::<sys::llhttp_settings_t>() == size_of::<[usize; 23]>()) };
46	    // SAFETY: the handle addresses a live table; `llhttp_settings_s` is 23 nullable function
47	    // pointers, each the size and alignment of a `usize`, with no padding (asserted above),
48	    // and reading their bits as integers forms no function pointer.
49	    unsafe { settings.as_ptr().cast::<[usize; 23]>().read() }
50	}
51	
52	/// The parser's bytes, private state included: every field is an integer or a pointer, and
53	/// `llhttp__internal_s` has no padding but what `memset` and the field writes cover.
54	fn raw_parser(parser: ParserRef<'_>) -> sys::llhttp__internal_s {
55	    // SAFETY: the handle addresses a live parser; `llhttp__internal_s` is `Copy`, its fields
56	    // integers and pointers, so a copy of it forms nothing it does not hold.
57	    unsafe { parser.as_ptr().read() }
58	}
59	
60	/// `parser`'s fields that a parse writes, compared as integers and addresses, `data` and
61	/// `settings` included.
62	fn fields(p: &sys::llhttp__internal_s) -> impl PartialEq + std::fmt::Debug + use<> {
63	    (
64	        (p._index, p._span_pos0.addr(), p._span_cb0.addr()),
65	        (p.error, p.reason.addr(), p.error_pos.addr()),
66	        (p.data.addr(), p._current.addr(), p.content_length, p.type_),
67	        (p.method, p.http_major, p.http_minor, p.header_state),
68	        (p.lenient_flags, p.upgrade, p.finish, p.flags, p.status_code),
69	        (p.initial_message_completed, p.settings.addr()),
70	    )
71	}
72	
73	thread_local! {
74	    /// The slots C's dispatchers called, by index, with each data slot's run.
75	    static LOG: RefCell<Vec<(usize, Vec<u8>)>> = const { RefCell::new(Vec::new()) };
76	}
77	
78	/// Records that slot `N` was called, and returns `0`.
79	struct Event<const N: usize>;
80	
81	impl<const N: usize> EventHandler for Event<N> {
82	    fn on_event(_: ParserMut<'_>) -> c_int {
83	        LOG.with_borrow_mut(|log| log.push((N, Vec::new())));
84	        0
85	    }
86	}
87	
88	/// Records that slot `N` was called with `data`, and returns `0`.
89	struct Data<const N: usize>;
90	
91	impl<const N: usize> DataHandler for Data<N> {
92	    fn on_data(_: ParserMut<'_>, data: &[u8]) -> c_int {
93	        LOG.with_borrow_mut(|log| log.push((N, data.to_vec())));
94	        0
95	    }
96	}
97	
98	/// Calls `$m!(index, field, setter, kind)` for each slot, in `llhttp_settings_s`' order.
99	macro_rules! for_each_slot {
100	    ($m:ident) => {
101	        $m!(0, on_message_begin, set_on_message_begin, event);
102	        $m!(1, on_url, set_on_url, data);
103	        $m!(2, on_status, set_on_status, data);
104	        $m!(3, on_method, set_on_method, data);
105	        $m!(4, on_version, set_on_version, data);
106	        $m!(5, on_header_field, set_on_header_field, data);
107	        $m!(6, on_header_value, set_on_header_value, data);
108	        $m!(
109	            7,
110	            on_chunk_extension_name,
111	            set_on_chunk_extension_name,
112	            data
113	        );
114	        $m!(
115	            8,
116	            on_chunk_extension_value,
117	            set_on_chunk_extension_value,
118	            data
119	        );
120	        $m!(9, on_headers_complete, set_on_headers_complete, event);
121	        $m!(10, on_body, set_on_body, data);
122	        $m!(11, on_message_complete, set_on_message_complete, event);
123	        $m!(12, on_url_complete, set_on_url_complete, event);
124	        $m!(13, on_status_complete, set_on_status_complete, event);
125	        $m!(14, on_method_complete, set_on_method_complete, event);
126	        $m!(15, on_version_complete, set_on_version_complete, event);
127	        $m!(
128	            16,
129	            on_header_field_complete,
130	            set_on_header_field_complete,
131	            event
132	        );
133	        $m!(
134	            17,
135	            on_header_value_complete,
136	            set_on_header_value_complete,
137	            event
138	        );
139	        $m!(
140	            18,
141	            on_chunk_extension_name_complete,
142	            set_on_chunk_extension_name_complete,
143	            event
144	        );
145	        $m!(
146	            19,
147	            on_chunk_extension_value_complete,
148	            set_on_chunk_extension_value_complete,
149	            event
150	        );
151	        $m!(20, on_chunk_header, set_on_chunk_header, event);
152	        $m!(21, on_chunk_complete, set_on_chunk_complete, event);
153	        $m!(22, on_reset, set_on_reset, event);
154	    };
155	}
156	
157	/// The same slots of two tables, `rust` through the setters and `c` as C fills its fields:
158	/// each slot whose bit is set in `mask` records.
159	fn fill_both(mask: u32, rust: &mut Settings, c: &mut sys::llhttp_settings_t) {
160	    let mut m = rust.as_mut();
161	    macro_rules! fill {
162	        ($i:expr, $field:ident, $set:ident,event) => {
163	            if mask & (1 << $i) != 0 {
164	                let callback = Callback::new::<Event<$i>>();
165	                m.$set(Some(callback));
166	                c.$field = callback.raw();
167	            }
168	        };
169	        ($i:expr, $field:ident, $set:ident,data) => {
170	            if mask & (1 << $i) != 0 {
171	                let callback = DataCallback::new::<Data<$i>>();
172	                m.$set(Some(callback));
173	                c.$field = callback.raw();
174	            }
175	        };
176	    }
177	    for_each_slot!(fill);
178	}
179	
180	/// A table that lives as long as the test process, for the parsers given it: leaked, its
181	/// address kept in a global so that the leak checker the address sanitizer runs at exit finds it
182	/// still reachable.
183	fn kept() -> &'static mut Settings {
184	    static KEPT: Mutex<Vec<usize>> = Mutex::new(Vec::new());
185	    let settings: &'static mut Settings = Box::leak(Box::default());
186	    KEPT.lock()
187	        .unwrap()
188	        .push(std::ptr::from_mut(settings).addr());
189	    settings
190	}
191	
192	/// A table C initialised with `llhttp_settings_init`, from garbage.
193	fn c_settings_init() -> sys::llhttp_settings_t {
194	    let mut c = MaybeUninit::<sys::llhttp_settings_t>::uninit();
195	    // SAFETY: `c` is writable storage of the table's size; the bytes are only overwritten.
196	    unsafe {
197	        c.as_mut_ptr()
198	            .cast::<u8>()
199	            .write_bytes(0xA5, size_of::<sys::llhttp_settings_t>());
200	    };
201	    // SAFETY: `c` is a table's writable storage, which `llhttp_settings_init` `memset`s whole.
202	    unsafe { sys::llhttp_settings_init(c.as_mut_ptr()) };
203	    // SAFETY: `llhttp_settings_init` wrote every byte: all-zero, every slot NULL.
204	    unsafe { c.assume_init() }
205	}
