207	#[test]
208	#[cfg_attr(miri, ignore = "calls C")]
209	fn new_leaves_the_table_as_llhttp_settings_init_does() {
210	    let c = c_settings_init();
211	    let rust = Settings::new();
212	    // SAFETY: `c` is a live table Rust owns, read for the handle's borrow.
213	    let c_ref = unsafe { SettingsRef::from_ptr((&raw const c).cast_mut()) }.unwrap();
214	    assert_eq!(raw_slots(rust.as_ref()), raw_slots(c_ref));
215	    assert_eq!(raw_slots(rust.as_ref()), [0; 23]);
216	    assert_eq!(raw_slots(Settings::zeroed().as_ref()), raw_slots(c_ref));
217	}
218	
219	#[test]
220	#[cfg_attr(miri, ignore = "calls C")]
221	fn the_setters_fill_the_table_as_c_fills_its_fields() {
222	    // Every slot alone, then a few combinations, then all of them.
223	    let masks = (0..23)
224	        .map(|i| 1u32 << i)
225	        .chain([0x55_5555, 0x2A_AAAA, (1 << 23) - 1]);
226	    for mask in masks {
227	        let mut rust = Settings::new();
228	        let mut c = c_settings_init();
229	        fill_both(mask, &mut rust, &mut c);
230	        // SAFETY: `c` is a live table Rust owns, filled only with `Callback` and
231	        // `DataCallback` values, as a `SettingsRef`'s invariant asks.
232	        let c_ref = unsafe { SettingsRef::from_ptr((&raw const c).cast_mut()) }.unwrap();
233	        assert_eq!(raw_slots(rust.as_ref()), raw_slots(c_ref), "{mask:#x}");
234	        // A table C filled reads back through the getters as the one the setters filled.
235	        assert_eq!(format!("{:?}", rust.as_ref()), format!("{c_ref:?}"));
236	    }
237	}
