239	/// Two parsers given one table: `c` by `llhttp_init`, `rust` by `Parser::new` and the safe
240	/// setters.
241	fn both_given(parser_type: ParserType, settings: &'static Settings) -> (Parser, Parser) {
242	    let mut c = Parser::zeroed();
243	    // SAFETY: the handle addresses `c`, a live parser Rust owns, which `llhttp_init` fills in
244	    // place; `settings` is `'static`, and its slots are Rust handlers sound with any parser.
245	    unsafe {
246	        sys::llhttp_init(
247	            c.as_mut().as_mut_ptr(),
248	            parser_type.raw(),
249	            settings.as_ref().as_ptr(),
250	        );
251	    };
252	    let mut rust = Parser::new();
253	    rust.as_mut().set_parser_type(parser_type);
254	    rust.as_mut().set_settings(Some(settings.as_ref()));
255	    (c, rust)
256	}
257	
258	/// A kept table whose slots in `mask` record.
259	fn leaked(mask: u32) -> &'static Settings {
260	    let rust: &'static mut Settings = kept();
261	    let mut c = c_settings_init();
262	    fill_both(mask, rust, &mut c);
263	    rust
264	}
