266	#[test]
267	#[cfg_attr(miri, ignore = "calls C")]
268	fn set_settings_leaves_the_parser_as_llhttp_init_does() {
269	    for parser_type in [ParserType::Both, ParserType::Request, ParserType::Response] {
270	        let settings = leaked((1 << 23) - 1);
271	        let (mut c, mut rust) = both_given(parser_type, settings);
272	        assert_eq!(
273	            fields(&raw_parser(rust.as_ref())),
274	            fields(&raw_parser(c.as_ref()))
275	        );
276	        // `llhttp_reset` keeps the table either way.
277	        for parser in [&mut c, &mut rust] {
278	            // SAFETY: the parser is initialised, and its table is `'static`.
279	            unsafe { sys::llhttp_reset(parser.as_mut().as_mut_ptr()) };
280	            assert_eq!(
281	                parser.as_ref().settings_ptr().addr(),
282	                std::ptr::from_ref(settings).addr()
283	            );
284	        }
285	        assert_eq!(
286	            fields(&raw_parser(rust.as_ref())),
287	            fields(&raw_parser(c.as_ref()))
288	        );
