292	/// What a run returned, and the slots it called.
293	type Step = (u32, Vec<(usize, Vec<u8>)>);
294	
295	/// `llhttp_finish` on `parser`, which calls `on_message_complete` through its table.
296	fn c_finish(parser: &mut Parser) -> Step {
297	    // SAFETY: `parser` is initialised, and its table is `'static` and holds only Rust
298	    // handlers.
299	    let errno = unsafe { sys::llhttp_finish(parser.as_mut().as_mut_ptr()) };
300	    (errno, LOG.take())
301	}
302	
303	/// Feeds `runs` to `parser` through `llhttp_execute`, then finishes it.
304	fn c_runs(parser: &mut Parser, runs: &[&[u8]]) -> Vec<Step> {
305	    let mut out = Vec::new();
306	    for run in runs {
307	        // SAFETY: `parser` is initialised, `run` is `run.len()` live bytes, and its table is
308	        // `'static` and holds only Rust handlers.
309	        let errno = unsafe {
310	            sys::llhttp_execute(parser.as_mut().as_mut_ptr(), run.as_ptr().cast(), run.len())
311	        };
312	        out.push((errno, LOG.take()));
313	    }
314	    out.push(c_finish(parser));
315	    out
316	}
317	
318	/// Feeds `runs` to `parser` through [`ParserMut::parse`], then finishes it through C.
319	fn rust_runs(parser: &mut Parser, runs: &[&[u8]]) -> Vec<Step> {
320	    let mut out = Vec::new();
321	    for run in runs {
322	        let errno = match parser.as_mut().parse(run) {
323	            Ok(Parsed::All) => sys::HPE_OK,
324	            Ok(Parsed::Paused) => sys::HPE_PAUSED,
325	            Ok(Parsed::PausedUpgrade) => sys::HPE_PAUSED_UPGRADE,
326	            Err(error) => error.code().cast_unsigned(),
327	        };
328	        out.push((errno, LOG.take()));
329	    }
330	    out.push(c_finish(parser));
331	    out
332	}
