338	        (
339	            ParserType::Response,
340	            (1 << 23) - 1,
341	            &[
342	                b"HTTP/1.1 200 OK\r\nContent-",
343	                b"Length: 3\r\nX: y\r\n\r\nab",
344	                b"cHTTP/1.1 204 No Content\r\n\r\n",
345	            ],
346	        ),
347	        (
348	            ParserType::Request,
349	            0x55_5555,
350	            &[
351	                b"POST /u?q HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n2;e=f\r\nhi\r\n",
352	                b"0\r\n\r\n",
353	            ],
354	        ),
355	        (
356	            ParserType::Both,
357	            0x2A_AAAA,
358	            &[
359	                b"GET / HTTP/1.1\r\nHost: h\r\n\r\n",
360	                b"HTTP/1.1 304 X\r\n\r\n",
361	            ],
362	        ),
363	        // A response read to the end of its connection, which `llhttp_finish` completes.
364	        (
365	            ParserType::Response,
