371	        let settings = leaked(mask);
372	        let (mut c, mut rust) = both_given(parser_type, settings);
373	        let c_out = c_runs(&mut c, runs);
374	        let rust_out = rust_runs(&mut rust, runs);
375	        assert_eq!(rust_out, c_out, "{parser_type:?} {mask:#x}");
376	        assert!(c_out.iter().any(|(_, log)| !log.is_empty()));
