384	// --- The parser's API ------------------------------------------------------------------
385	
386	/// `parser`'s fields as [`fields`] compares them, but for its reason, which is compared by
387	/// its text: llhttp's literals and Rust's are distinct copies of one text.
388	fn state(parser: ParserRef<'_>) -> impl PartialEq + std::fmt::Debug + use<> {
389	    let mut raw = raw_parser(parser);
390	    raw.reason = core::ptr::null();
391	    (fields(&raw), parser.reason().map(CStr::to_owned))
392	}
