394	/// One of the three calls that move a parser between running and paused.
395	#[derive(Clone, Copy, Debug)]
396	enum Call {
397	    Pause,
398	    Resume,
399	    ResumeAfterUpgrade,
400	}
401	
402	impl Call {
403	    /// Makes the call through C.
404	    fn c(self, parser: &mut Parser) {
405	        let raw = parser.as_mut().as_mut_ptr();
406	        match self {
407	            // SAFETY: `raw` addresses a live parser Rust owns; each call reads and writes
408	            // only its `error` and `reason`.
409	            Self::Pause => unsafe { sys::llhttp_pause(raw) },
410	            // SAFETY: as above.
411	            Self::Resume => unsafe { sys::llhttp_resume(raw) },
412	            // SAFETY: as above.
413	            Self::ResumeAfterUpgrade => unsafe { sys::llhttp_resume_after_upgrade(raw) },
414	        }
415	    }
416	
417	    /// Makes the call through Rust.
418	    fn rust(self, parser: &mut Parser) {
419	        match self {
420	            Self::Pause => parser.as_mut().pause(),
421	            Self::Resume => parser.as_mut().resume(),
422	            Self::ResumeAfterUpgrade => parser.as_mut().resume_after_upgrade(),
423	        }
424	    }
425	}
426	
427	/// A response parser fed `input` through C, from `Parser::new`.
428	fn fed(input: &[u8]) -> Parser {
429	    let mut parser = Parser::new();
430	    parser.as_mut().set_parser_type(ParserType::Response);
431	    // SAFETY: the parser is initialised and has no settings; `input` is live for the call.
432	    unsafe {
433	        sys::llhttp_execute(
434	            parser.as_mut().as_mut_ptr(),
435	            input.as_ptr().cast(),
436	            input.len(),
437	        )
438	    };
439	    parser
440	}
441	
442	#[test]
443	#[cfg_attr(miri, ignore = "calls C")]
444	fn pause_and_the_resumptions_move_the_parser_as_c_does() {
445	    const UPGRADE: &[u8] = b"HTTP/1.1 101 Switching Protocols\r\nConnection: upgrade\r\n\
446	                             Upgrade: x\r\n\r\n";
447	    // A parser running, paused at an upgrade, and failed; the pause each call makes from
448	    // them reaches the paused state too.
449	    let starts: [&[u8]; 4] = [b"", b"HTTP/1.1 200 OK\r\n", UPGRADE, b"HTTP/9"];
450	    let calls = [Call::Pause, Call::Resume, Call::ResumeAfterUpgrade];
451	    for start in starts {
452	        for first in calls {
453	            for second in calls {
454	                let (mut c, mut rust) = (fed(start), fed(start));
455	                for call in [first, second] {
456	                    call.c(&mut c);
457	                    call.rust(&mut rust);
458	                    assert_eq!(
459	                        state(rust.as_ref()),
460	                        state(c.as_ref()),
461	                        "{start:?}: {first:?}, {second:?}"
462	                    );
463	                }
464	            }
465	        }
466	    }
467	}
