469	/// What a run returned through `llhttp_execute`'s convention.
470	fn code(outcome: Result<Parsed, ParseError>) -> u32 {
471	    match outcome {
472	        Ok(Parsed::All) => sys::HPE_OK,
473	        Ok(Parsed::Paused) => sys::HPE_PAUSED,
474	        Ok(Parsed::PausedUpgrade) => sys::HPE_PAUSED_UPGRADE,
475	        Err(error) => error.code().cast_unsigned(),
476	    }
477	}
478	
479	/// A step of a sequence fed to two parsers: a run of the input, or a call.
480	enum Action {
481	    Run(&'static [u8]),
482	    Do(Call),
483	}
484	
485	#[test]
486	#[cfg_attr(miri, ignore = "calls C")]
487	fn execute_reads_runs_between_pauses_as_llhttp_execute_does() {
488	    use Action::{Do, Run};
489	    let sequences: [&[Action]; 3] = [
490	        &[
491	            Run(b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n"),
492	            Do(Call::Pause),
493	            Run(b"\r\nhi"),
494	            Do(Call::Resume),
495	            Run(b"\r\nhi"),
496	            Run(b"HTTP/1.1 204 No Content\r\n\r\n"),
497	        ],
498	        &[
499	            Run(b"HTTP/1.1 101 Switching Protocols\r\nConnection: upgrade\r\nUpgrade: x\r\n\r\nbytes"),
500	            Run(b"more"),
501	            Do(Call::Resume),
502	            Run(b"more"),
503	            Do(Call::ResumeAfterUpgrade),
504	            Run(b"HTTP/1.1 200 OK\r\n"),
505	        ],
506	        &[
507	            Run(b"HTTP/1.1 200 OK\r\nBad Header\r\n"),
508	            Do(Call::Pause),
509	            Do(Call::Resume),
510	            Run(b"\r\n"),
511	        ],
512	    ];
513	    for steps in sequences {
514	        let (mut c, mut rust) = (Parser::new(), Parser::new());
515	        for step in steps {
516	            match step {
517	                Run(run) => {
518	                    // SAFETY: the parser is initialised and has no settings; `run` is live.
519	                    let c_code = unsafe {
520	                        sys::llhttp_execute(c.as_mut().as_mut_ptr(), run.as_ptr().cast(), run.len())
521	                    };
522	                    assert_eq!(code(rust.as_mut().execute(run)), c_code);
523	                }
524	                Do(call) => {
525	                    call.c(&mut c);
526	                    call.rust(&mut rust);
527	                }
528	            }
529	            assert_eq!(state(rust.as_ref()), state(c.as_ref()));
530	        }
531	    }
532	}
