534	/// A lenient setter through Rust and through C.
535	type LenientPair = (
536	    fn(&mut ParserMut<'_>, bool),
537	    unsafe extern "C" fn(*mut sys::llhttp_t, c_int),
538	);
539	
540	/// The ten lenient setters, Rust's beside C's.
541	const LENIENT: [LenientPair; 10] = [
542	    (
543	        |p, on| p.set_lenient_headers(on),
544	        sys::llhttp_set_lenient_headers,
545	    ),
546	    (
547	        |p, on| p.set_lenient_chunked_length(on),
548	        sys::llhttp_set_lenient_chunked_length,
549	    ),
550	    (
551	        |p, on| p.set_lenient_keep_alive(on),
552	        sys::llhttp_set_lenient_keep_alive,
553	    ),
554	    (
555	        |p, on| p.set_lenient_transfer_encoding(on),
556	        sys::llhttp_set_lenient_transfer_encoding,
557	    ),
558	    (
559	        |p, on| p.set_lenient_version(on),
560	        sys::llhttp_set_lenient_version,
561	    ),
562	    (
563	        |p, on| p.set_lenient_data_after_close(on),
564	        sys::llhttp_set_lenient_data_after_close,
565	    ),
566	    (
567	        |p, on| p.set_lenient_optional_lf_after_cr(on),
568	        sys::llhttp_set_lenient_optional_lf_after_cr,
569	    ),
570	    (
571	        |p, on| p.set_lenient_optional_crlf_after_chunk(on),
572	        sys::llhttp_set_lenient_optional_crlf_after_chunk,
573	    ),
574	    (
575	        |p, on| p.set_lenient_optional_cr_before_lf(on),
576	        sys::llhttp_set_lenient_optional_cr_before_lf,
577	    ),
578	    (
579	        |p, on| p.set_lenient_spaces_after_chunk_size(on),
580	        sys::llhttp_set_lenient_spaces_after_chunk_size,
581	    ),
582	];
