584	#[test]
585	#[cfg_attr(miri, ignore = "calls C")]
586	fn the_lenient_setters_set_the_flags_as_c_does() {
587	    // C reads any nonzero `enabled` as true.
588	    let sequence: [c_int; 6] = [1, 1, 0, 7, -1, 0];
589	    for start in [0, 0x155, 0x3FF] {
590	        for (rust_set, c_set) in LENIENT {
591	            let (mut c, mut rust) = (Parser::zeroed(), Parser::zeroed());
592	            c.as_mut().set_lenient_flags_raw(start);
593	            rust.as_mut().set_lenient_flags_raw(start);
594	            for enabled in sequence {
595	                // SAFETY: the handle addresses a live parser Rust owns; the setter writes
596	                // only its `lenient_flags`.
597	                unsafe { c_set(c.as_mut().as_mut_ptr(), enabled) };
598	                rust_set(&mut rust.as_mut(), enabled != 0);
599	                assert_eq!(
600	                    fields(&raw_parser(rust.as_ref())),
601	                    fields(&raw_parser(c.as_ref()))
602	                );
603	            }
604	        }
605	    }
606	    // Every setter's bit, from the same start, gives every flag.
607	    let (mut c, mut rust) = (Parser::zeroed(), Parser::zeroed());
608	    for (rust_set, c_set) in LENIENT {
609	        // SAFETY: as above.
610	        unsafe { c_set(c.as_mut().as_mut_ptr(), 1) };
611	        rust_set(&mut rust.as_mut(), true);
612	    }
613	    assert_eq!(
614	        rust.as_ref().lenient_flags_raw(),
615	        c.as_ref().lenient_flags_raw()
616	    );
617	}
