636	// --- The parser's lifecycle -------------------------------------------------------------
637	
638	/// The states init, reset and finish are compared from, each a response parser fed its input
639	/// through C from `Parser::new`: fresh, inside a message, between two, failed, paused, and
640	/// a parser of both kinds that settled on a request.
641	const STARTS: [(ParserType, &[u8]); 6] = [
642	    (ParserType::Response, b""),
643	    (
644	        ParserType::Response,
645	        b"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhi",
646	    ),
647	    (ParserType::Response, b"HTTP/1.1 204 No Content\r\n\r\n"),
648	    (ParserType::Response, b"HTTP/9"),
649	    (
650	        ParserType::Response,
651	        b"HTTP/1.1 101 Switching Protocols\r\nConnection: upgrade\r\nUpgrade: x\r\n\r\n",
652	    ),
653	    (ParserType::Both, b"GET / HTTP/1.1\r\n\r\n"),
654	];
655	
656	/// A parser brought to `start` through C, with the table `settings`, lenient flags and a
657	/// `data` no callback reads.
658	fn started((parser_type, input): (ParserType, &[u8]), settings: &'static Settings) -> Parser {
659	    let mut parser = Parser::new();
660	    parser.as_mut().set_parser_type(parser_type);
661	    parser.as_mut().set_settings(Some(settings.as_ref()));
662	    parser.as_mut().set_lenient_keep_alive(true);
663	    parser.as_mut().set_lenient_version(true);
664	    // SAFETY: the table's callbacks are Rust handlers that never read `data`, so any value
665	    // meets `set_data`'s contract; this one is only compared.
666	    unsafe { parser.as_mut().set_data(core::ptr::dangling_mut()) };
667	    // SAFETY: the parser is initialised, its table `'static` and of Rust handlers; `input` is
668	    // live for the call.
669	    unsafe {
670	        sys::llhttp_execute(
671	            parser.as_mut().as_mut_ptr(),
672	            input.as_ptr().cast(),
673	            input.len(),
674	        )
675	    };
676	    LOG.take();
677	    parser
678	}
679	
680	#[test]
681	#[cfg_attr(miri, ignore = "calls C")]
682	fn init_leaves_the_parser_as_llhttp_init_does() {
683	    let settings = leaked((1 << 23) - 1);
684	    let other = leaked(0x55_5555);
685	    for start in STARTS {
686	        for parser_type in [ParserType::Both, ParserType::Request, ParserType::Response] {
687	            let (mut c, mut rust) = (started(start, settings), started(start, settings));
688	            // SAFETY: the parser is live and Rust's; `other` is `'static` and of Rust handlers.
689	            unsafe {
690	                sys::llhttp_init(
691	                    c.as_mut().as_mut_ptr(),
692	                    parser_type.raw(),
693	                    other.as_ref().as_ptr(),
694	                );
695	            };
696	            rust.as_mut().init(parser_type, Some(other.as_ref()));
697	            assert_eq!(
698	                state(rust.as_ref()),
699	                state(c.as_ref()),
700	                "{start:?} {parser_type:?}"
701	            );
702	            // Both parse the same next message.
703	            let next = b"HTTP/1.1 200 OK\r\n\r\n";
704	            assert_eq!(rust_runs(&mut rust, &[next]), c_runs(&mut c, &[next]));
705	        }
706	    }
707	}
