709	#[test]
710	#[cfg_attr(miri, ignore = "calls C")]
711	fn reset_leaves_the_parser_as_llhttp_reset_does() {
712	    let settings = leaked((1 << 23) - 1);
713	    for start in STARTS {
714	        let (mut c, mut rust) = (started(start, settings), started(start, settings));
715	        // SAFETY: the parser is live and Rust's, its table `'static` and of Rust handlers.
716	        unsafe { sys::llhttp_reset(c.as_mut().as_mut_ptr()) };
717	        rust.as_mut().reset();
718	        assert_eq!(state(rust.as_ref()), state(c.as_ref()), "{start:?}");
719	        assert!(!rust.as_ref().data().is_null());
720	        let next = b"HTTP/1.1 200 OK\r\nContent-Length: 1\r\n\r\nx";
721	        assert_eq!(
722	            rust_runs(&mut rust, &[next]),
723	            c_runs(&mut c, &[next]),
724	            "{start:?}"
725	        );
726	    }
727	}
728	
729	/// Returns `R` from `on_message_complete`, recording it as slot 11.
730	struct CompleteReturn<const R: c_int>;
731	
732	impl<const R: c_int> EventHandler for CompleteReturn<R> {
733	    fn on_event(_: ParserMut<'_>) -> c_int {
734	        LOG.with_borrow_mut(|log| log.push((11, Vec::new())));
735	        R
736	    }
737	}
738	
739	/// A kept table that records every slot, its `on_message_complete` returning `R`.
740	fn completing<const R: c_int>() -> &'static Settings {
741	    let settings = kept();
742	    let mut c = c_settings_init();
743	    fill_both((1 << 23) - 1, settings, &mut c);
744	    settings
745	        .as_mut()
746	        .set_on_message_complete(Some(Callback::new::<CompleteReturn<R>>()));
747	    settings
748	}
749	
750	/// `ParserMut::finish` on `parser`, through `llhttp_finish`'s convention.
751	fn rust_finish(parser: &mut Parser) -> Step {
752	    let errno = match parser.as_mut().finish() {
753	        Ok(()) => sys::HPE_OK,
754	        Err(error) => error.code().cast_unsigned(),
755	    };
756	    (errno, LOG.take())
757	}
758	
759	#[test]
760	#[cfg_attr(miri, ignore = "calls C")]
761	fn finish_finishes_the_parser_as_llhttp_finish_does() {
762	    let tables = [completing::<0>(), completing::<-1>(), completing::<21>()];
763	    let ends: [&[u8]; 3] = [
764	        b"",
765	        b"HTTP/1.0 200 OK\r\n\r\nto the end",
766	        b"HTTP/1.1 200 OK\r\n",
767	    ];
768	    for settings in tables {
769	        for start in STARTS
770	            .into_iter()
771	            .chain(ends.map(|end| (ParserType::Response, end)))
772	        {
773	            let (mut c, mut rust) = (started(start, settings), started(start, settings));
774	            // Twice: a finish that ended a message leaves one that may end again.
775	            for _ in 0..2 {
776	                assert_eq!(rust_finish(&mut rust), c_finish(&mut c), "{start:?}");
777	                assert_eq!(state(rust.as_ref()), state(c.as_ref()), "{start:?}");
778	            }
779	            // A finish state no `llhttp_finish` names is refused, where C aborts; the others
780	            // are each reached above or here.
781	            for finish in 0..3 {
782	                rust.as_mut().set_finish_raw(finish);
783	                c.as_mut().set_finish_raw(finish);
784	                assert_eq!(
785	                    rust_finish(&mut rust),
786	                    c_finish(&mut c),
787	                    "{start:?} {finish}"
788	                );
789	                assert_eq!(
790	                    state(rust.as_ref()),
791	                    state(c.as_ref()),
792	                    "{start:?} {finish}"
793	                );
794	            }
795	        }
796	    }
797	}
798	
799	// --- The dispatchers ---------------------------------------------------------------------
