    /// Replaces `fn::llhttp_set_lenient_optional_crlf_after_chunk`
    #[doc(alias = "llhttp_set_lenient_optional_crlf_after_chunk")]
    set_lenient_optional_crlf_after_chunk, LENIENT_OPTIONAL_CRLF_AFTER_CHUNK:
