                /// Replaces `fn::llhttp__on_body`
                #[doc(alias = "llhttp__on_body")]
                llhttp__on_body, on_body, Body: "a run of the message's body";
                /// Replaces `fn::llhttp__on_chunk_extension_name`
                #[doc(alias = "llhttp__on_chunk_extension_name")]
